/**
 * requirePlatformAdmin — shared guard for all /api/admin/* routes.
 *
 * Handles:
 *  - Rate-limiting via getClientIp (cf-connecting-ip aware — QA #22 / #77)
 *  - Supabase session check
 *  - is_platform_admin profile check
 *
 * Returns either a NextResponse error (caller must return it) or the authed user id.
 *
 * Usage:
 *   const result = await requirePlatformAdmin(req)
 *   if (result instanceof NextResponse) return result
 *   const { userId } = result
 */
import { NextResponse, type NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'

interface AdminContext {
  userId: string
}

export async function requirePlatformAdmin(
  req: NextRequest,
): Promise<NextResponse | AdminContext> {
  const ip = getClientIp(req)
  const { success } = await authedRatelimit.limit(ip)
  if (!success) {
    return NextResponse.json({ error: 'rate limit exceeded' }, { status: 429 })
  }

  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    return NextResponse.json({ error: 'unauthorized' }, { status: 401 })
  }

  const { data: profile } = await supabase
    .from('profiles')
    .select('is_platform_admin')
    .eq('id', user.id)
    .single()

  if (!profile?.is_platform_admin) {
    return NextResponse.json({ error: 'forbidden' }, { status: 403 })
  }

  return { userId: user.id }
}

