import { NextResponse, type NextRequest } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { requirePlatformAdmin } from '@/lib/admin/require-platform-admin'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

interface Params { params: Promise<{ id: string }> }

const bodySchema = z.object({
  action: z.enum(['ban', 'unban']),
  reason: z.string().max(500).optional(),
})

export async function POST(req: NextRequest, { params }: Params) {
  const guard = await requirePlatformAdmin(req)
  if (guard instanceof NextResponse) return guard
  const { userId } = guard

  const body = bodySchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  const { id: studioId } = await params
  const { action, reason } = body.data
  const admin = createServiceRoleClient()

  try {
    const newStatus: 'banned' | 'active' = action === 'ban' ? 'banned' : 'active'
    const { error } = await admin
      .from('studios')
      .update({ status: newStatus, updated_at: new Date().toISOString() })
      .eq('id', studioId)

    if (error) throw error

    await logAuditAction(
      userId,
      `admin.studio.${action}`,
      { type: 'studio', id: studioId },
      { reason: reason ?? null, new_status: newStatus },
      null
    )

    return NextResponse.json({ status: newStatus })
  } catch (err) {
    logger.error({ err, studioId, action }, 'ban/unban failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

