/**
 * POST /api/admin/studios/[id]/impersonate
 * Generates a magic link for the studio owner.
 * Audit-logged. Single-use only (Supabase magic link is single-use by default).
 *
 * Note (#36): Supabase auth magic link TTL is a project-level setting
 * (Auth > Email > Magic link expiry). Set to 900s to match the advisory
 * 15-minute window shown in admin UI. expiresAt below is advisory only.
 *
 * Note (#67): action_link can be undefined if Supabase returns an error shape.
 * We guard with an explicit check rather than relying on optional chaining.
 */
export async function POST(req: NextRequest, { params }: Params) {
  const guard = await requirePlatformAdmin(req)
  if (guard instanceof NextResponse) return guard
  const { userId } = guard

  const { id: studioId } = await params
  const admin = createServiceRoleClient()

  try {
    // Find the studio owner — distinguish deactivated vs truly missing (#89)
    const ownerResult = await admin
      .from('studio_members')
      .select('user_id')
      .eq('studio_id', studioId)
      .eq('role', 'owner')
      .limit(1)
      .single()

    if (ownerResult.error || !ownerResult.data) {
      return NextResponse.json({ error: 'Studio owner not found' }, { status: 404 })
    }

    // Check if deactivated
    const memberWithStatus = await admin
      .from('studio_members')
      .select('deactivated_at')
      .eq('studio_id', studioId)
      .eq('user_id', ownerResult.data.user_id)
      .single()

    if (memberWithStatus.data?.deactivated_at) {
      return NextResponse.json({ error: 'Studio owner is deactivated — cannot impersonate' }, { status: 422 })
    }

    // Get owner email from auth admin API
    const { data: ownerAuthUser, error: authUserError } = await admin.auth.admin.getUserById(ownerResult.data.user_id)
    if (authUserError || !ownerAuthUser?.user?.email) {
      return NextResponse.json({ error: 'Owner email not found' }, { status: 404 })
    }

    const ownerEmail = ownerAuthUser.user.email

    const { data: linkData, error: linkError } = await admin.auth.admin.generateLink({
      type: 'magiclink',
      email: ownerEmail,
    })

    if (linkError || !linkData) {
      throw linkError ?? new Error('Failed to generate magic link')
    }

    // Guard action_link explicitly — can be undefined in error shapes (#67)
    const actionLink = linkData.properties?.action_link
    if (!actionLink) {
      throw new Error('Supabase did not return an action_link')
    }

    const expiresAt = new Date(Date.now() + 15 * 60 * 1000).toISOString()

    await logAuditAction(
      userId,
      'admin.impersonate',
      { type: 'studio', id: studioId },
      {
        target_email: ownerEmail,
        target_studio_id: studioId,
        expires_at: expiresAt,
      },
      null
    )

    return NextResponse.json({
      signInUrl: actionLink,
      expiresAt,
    })
  } catch (err) {
    logger.error({ err, studioId }, 'impersonate failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

