const querySchema = z.object({
  actor_id: z.string().uuid().optional(),
  action: z.string().max(100).optional(),
  target_type: z.string().max(50).optional(),
  from: z.string().datetime().optional(),
  to: z.string().datetime().optional(),
  page: z.coerce.number().int().positive().default(1),
  limit: z.coerce.number().int().min(1).max(100).default(50),
})

export async function GET(req: NextRequest) {
  const guard = await requirePlatformAdmin(req)
  if (guard instanceof NextResponse) return guard

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const { actor_id, action, target_type, from, to, page, limit } = parsed.data
  const admin = createServiceRoleClient()

  try {
    let query = admin
      .from('audit_log')
      .select('*, profiles!audit_log_actor_id_fkey(email, full_name)', { count: 'exact' })
