import { NextResponse, type NextRequest } from 'next/server'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { requirePlatformAdmin } from '@/lib/admin/require-platform-admin'
import { logger } from '@/lib/logger'

export async function GET(req: NextRequest) {
  const guard = await requirePlatformAdmin(req)
  if (guard instanceof NextResponse) return guard

  const admin = createServiceRoleClient()

  try {
    const [
      studiosCount,
      bannedCount,
      bookingsCount,
      subsData,
      newSignupsData,
    ] = await Promise.all([
      admin.from('studios').select('id', { count: 'exact', head: true }),
      admin.from('studios').select('id', { count: 'exact', head: true }).eq('status', 'banned'),
      admin.from('bookings').select('id', { count: 'exact', head: true }),
      admin.from('subscriptions')
        .select('plan_tier, status, created_at')
        .eq('status', 'active'),
      admin.from('studios')
        .select('created_at')
        .gte('created_at', new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString())
        .order('created_at'),
    ])

    const planPrices: Record<string, number> = { solo: 29, studio: 59, pro: 99, enterprise: 199 }
    const mrr = (subsData.data ?? []).reduce((sum, s) => sum + (planPrices[s.plan_tier] ?? 0), 0)
    const arr = mrr * 12

    const planBreakdown = (subsData.data ?? []).reduce<Record<string, number>>((acc, s) => {
      acc[s.plan_tier] = (acc[s.plan_tier] ?? 0) + 1
      return acc
    }, {})

    const signupsByDay = (newSignupsData.data ?? []).reduce<Record<string, number>>((acc, s) => {
      const day = s.created_at.slice(0, 10)
      acc[day] = (acc[day] ?? 0) + 1
      return acc
    }, {})

    const signupChart = Object.entries(signupsByDay)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([date, count]) => ({ date, count }))

    return NextResponse.json({
      totalStudios: studiosCount.count ?? 0,
      bannedStudios: bannedCount.count ?? 0,
      totalBookings: bookingsCount.count ?? 0,
      activeSubscriptions: subsData.data?.length ?? 0,
      mrr,
      arr,
      planBreakdown,
      signupChart,
    })
  } catch (err) {
    logger.error({ err }, 'admin overview failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

