import { requirePlatformAdmin } from '@/lib/admin/require-platform-admin'
import { logger } from '@/lib/logger'

const QuerySchema = z.object({
  from: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
  to: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).optional(),
})

export async function GET(req: NextRequest) {
  const guard = await requirePlatformAdmin(req)
  if (guard instanceof NextResponse) return guard

  const { searchParams } = new URL(req.url)
  const parsed = QuerySchema.safeParse(Object.fromEntries(searchParams.entries()))
  if (!parsed.success) return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })

  const now = new Date()
  const from = parsed.data.from ?? `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`
  const to = parsed.data.to ?? now.toISOString().substring(0, 10)

  const serviceSupabase = createServiceRoleClient()

  try {
    const { data, error } = await serviceSupabase.rpc('admin_get_ai_platform_usage', {
      p_from: from,
      p_to: to,
    })
    if (error) throw error
    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'admin_get_ai_platform_usage RPC failed')
    return NextResponse.json({ error: 'Failed to load platform usage data' }, { status: 500 })
  }
}

