import { redirect } from 'next/navigation'

// Settings index redirects to profile — avoids dead placeholder (#54)
export default function SettingsIndexPage() {
  redirect('/settings/profile')
}

import Link from 'next/link'
import { SettingsSidebar } from '@/components/settings/SettingsSidebar'
import { ScrollableTabs } from '@/components/shared/ScrollableTabs'

/**
 * Settings layout — Stripe/Vercel sidebar pattern.
 *
 * Desktop (≥ lg): Fixed 240px sidebar on left, scrollable content max-720px centered.
 * Mobile (< lg):  ScrollableTabs at top of content (sidebar collapses).
 *
 * Fixes:
 *  #61 — use next/link instead of <a> to avoid full-page reload on tab click
 *  #62/#88 — Locations points to /locations (not /settings/locations which doesn't exist)
 */
export default function SettingsLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <div className="flex min-h-[calc(100vh-57px)]">
      {/* Desktop sidebar */}
      <aside className="hidden lg:block border-r border-border/60 bg-background shrink-0">
        <SettingsSidebar />
      </aside>

      {/* Content area */}
      <div className="flex-1 min-w-0">
        {/* Mobile tab bar (hidden on lg+) */}
        <div className="lg:hidden border-b border-border/60 bg-background px-4 pt-2">
          <ScrollableTabs>
            <div className="flex gap-1 pb-2">
              {[
                { label: 'Profile',      href: '/settings/profile' },
                { label: 'Branding',     href: '/settings/branding' },
                { label: 'Locations',    href: '/locations' },
                { label: 'Policies',     href: '/settings/policies' },
                { label: 'Members',      href: '/settings/team' },
                { label: 'Services',     href: '/settings/services' },
                { label: 'Tags',         href: '/settings/tags' },
                { label: 'Ink Registry', href: '/settings/ink-registry' },
                { label: 'Integrations', href: '/settings/integrations' },
                { label: 'Billing',      href: '/settings/billing' },
              ].map((tab) => (
                <Link
                  key={tab.href}
                  href={tab.href}
                  className="shrink-0 rounded-md px-3 py-1.5 text-[13px] font-medium text-muted-foreground hover:bg-muted/50 hover:text-foreground transition-colors whitespace-nowrap"
                >
                  {tab.label}
                </Link>
              ))}
            </div>
          </ScrollableTabs>
        </div>

        {/* Page content */}
        <main id="main-content" className="max-w-[720px] mx-auto px-6 py-8">
          {children}
        </main>
      </div>
    </div>
  )
}

